72	              height: `${s.hPct}%`,
73	              zIndex: s.z,
74	              transform: `rotate(${s.rotationDeg}deg)`,
75	              filter: "drop-shadow(0 14px 18px rgba(0,0,0,.55))",
76	            };
77	            return (
78	              // eslint-disable-next-line @next/next/no-img-element
79	              <img key={p.id} src={p.imageUrl} alt={p.name} className="object-contain" style={style} />
80	            );
81	          })}
82	        </div>
83	
84	        <div className="px-6 pt-2">
85	          <Kicker>
86	            {outfit.occasion} · {outfit.weatherLabel}
87	          </Kicker>
88	          <h1 className="mt-2 font-serif text-[34px]/[1.04] text-foreground">{outfit.lookName}</h1>
89	
90	          {outfit.reasoning && (
